"""Estrae le immagini (XObject) da un PDF senza librerie esterne e le salva come PNG/JPG.
Uso: python -I estrai_img_pdf.py <file.pdf> <cartella_output>
Stampa anche la mappa pagina -> immagini e l'ordine di disegno nel content stream."""
import re
import sys
import zlib
import struct
import os

pdf_path, out_dir = sys.argv[1], sys.argv[2]
os.makedirs(out_dir, exist_ok=True)
data = open(pdf_path, 'rb').read()

# --- indicizza gli oggetti "N G obj ... endobj"
objs = {}
for m in re.finditer(rb'(\d+)\s+(\d+)\s+obj', data):
    num = int(m.group(1))
    start = m.end()
    end = data.find(b'endobj', start)
    objs[num] = data[start:end]


def get_dict_and_stream(body):
    """Restituisce (dizionario come bytes, stream grezzo o None)."""
    si = body.find(b'stream')
    if si == -1:
        return body, None
    d = body[:si]
    # lunghezza
    lm = re.search(rb'/Length\s+(\d+)(\s+(\d+)\s+R)?', d)
    s = si + len(b'stream')
    if data_slice_startswith(body, s, b'\r\n'):
        s += 2
    elif data_slice_startswith(body, s, b'\n'):
        s += 1
    if lm and not lm.group(2):
        ln = int(lm.group(1))
    elif lm and lm.group(2):
        ref = int(lm.group(1))
        ln = int(re.search(rb'(\d+)', objs[ref]).group(1))
    else:
        ln = body.find(b'endstream', s) - s
    return d, body[s:s + ln]


def data_slice_startswith(b, pos, pref):
    return b[pos:pos + len(pref)] == pref


def png_chunk(tag, payload):
    c = struct.pack('>I', len(payload)) + tag + payload
    return c + struct.pack('>I', zlib.crc32(tag + payload) & 0xffffffff)


def write_png(path, w, h, ncomp, raw, has_predictor):
    color_type = {1: 0, 3: 2, 4: 6}.get(ncomp, 2)
    if ncomp == 4:
        color_type = 6
    rowlen = w * ncomp
    if not has_predictor:
        rows = bytearray()
        for y in range(h):
            rows += b'\x00' + raw[y * rowlen:(y + 1) * rowlen]
        raw = bytes(rows)
    ihdr = struct.pack('>IIBBBBB', w, h, 8, color_type, 0, 0, 0)
    png = b'\x89PNG\r\n\x1a\n' + png_chunk(b'IHDR', ihdr) + png_chunk(b'IDAT', zlib.compress(raw, 6)) + png_chunk(b'IEND', b'')
    open(path, 'wb').write(png)


def ncomp_of(d):
    if b'/DeviceGray' in d:
        return 1
    if b'/DeviceCMYK' in d:
        return 4
    m = re.search(rb'/ColorSpace\s*\[\s*/ICCBased\s+(\d+)\s+\d+\s+R', d)
    if m:
        icc = objs[int(m.group(1))]
        n = re.search(rb'/N\s+(\d+)', icc)
        return int(n.group(1)) if n else 3
    return 3


images = {}
for num, body in objs.items():
    if b'/Subtype /Image' not in body[:600] and b'/Subtype/Image' not in body[:600]:
        continue
    d, st = get_dict_and_stream(body)
    w = int(re.search(rb'/Width\s+(\d+)', d).group(1))
    h = int(re.search(rb'/Height\s+(\d+)', d).group(1))
    is_smask = False
    images[num] = (w, h, d)
    if b'/DCTDecode' in d:
        path = os.path.join(out_dir, f'img_{num}.jpg')
        open(path, 'wb').write(st)
    elif b'/FlateDecode' in d:
        raw = zlib.decompress(st)
        nc = ncomp_of(d)
        pred = re.search(rb'/Predictor\s+(\d+)', d)
        has_pred = bool(pred and int(pred.group(1)) >= 10)
        path = os.path.join(out_dir, f'img_{num}.png')
        try:
            write_png(path, w, h, nc, raw, has_pred)
        except Exception as e:
            print('errore', num, e)
    else:
        print('filtro non gestito', num, d[:200])

# --- pagine
pages = []
for num, body in objs.items():
    if re.search(rb'/Type\s*/Page(?!s)', body):
        pages.append(num)
# ordine delle pagine: segue /Kids del nodo Pages radice
kids_order = []
for num, body in objs.items():
    if re.search(rb'/Type\s*/Pages', body):
        km = re.search(rb'/Kids\s*\[([^\]]*)\]', body)
        if km:
            refs = [int(x) for x in re.findall(rb'(\d+)\s+0\s+R', km.group(1))]
            kids_order.append((num, refs))
print('Nodi Pages:', kids_order)


def resolve_order(node):
    body = objs[node]
    if re.search(rb'/Type\s*/Page(?!s)', body):
        return [node]
    km = re.search(rb'/Kids\s*\[([^\]]*)\]', body)
    out = []
    for r in re.findall(rb'(\d+)\s+0\s+R', km.group(1)):
        out += resolve_order(int(r))
    return out

root_candidates = [n for n, b in objs.items() if re.search(rb'/Type\s*/Pages', b) and b'/Parent' not in b]
ordered = resolve_order(root_candidates[0]) if root_candidates else pages
for i, p in enumerate(ordered, 1):
    body = objs[p]
    # XObject della pagina (diretti o via Resources referenziate)
    res = body
    rm = re.search(rb'/Resources\s+(\d+)\s+0\s+R', body)
    if rm:
        res = objs[int(rm.group(1))]
    xo = re.search(rb'/XObject\s*<<(.*?)>>', res, re.S)
    xmap = {}
    if xo:
        for name, ref in re.findall(rb'/(\w+)\s+(\d+)\s+0\s+R', xo.group(1)):
            xmap[name.decode()] = int(ref)
    # content stream: ordine dei Do
    cm = re.search(rb'/Contents\s+(\d+)\s+0\s+R', body)
    drawn = []
    if cm:
        d, st = get_dict_and_stream(objs[int(cm.group(1))])
        try:
            cs = zlib.decompress(st) if b'/FlateDecode' in d else st
        except Exception:
            cs = b''
        for nm in re.findall(rb'/(\w+)\s+Do', cs):
            drawn.append(nm.decode())
        txt = re.findall(rb'\((.*?)\)\s*Tj', cs)
    info = []
    for nm in drawn:
        ref = xmap.get(nm)
        if ref in images:
            w, h, _ = images[ref]
            info.append(f'{nm}->obj{ref} {w}x{h}')
        else:
            # potrebbe essere un Form XObject che contiene immagini
            info.append(f'{nm}->obj{ref} (form?)')
    print(f'Pagina {i} (obj {p}): ' + '; '.join(info))

